let adminPermissionDraft={};let confirmedSection='active',confirmedArchiveOpen={},confirmedPending={};let billSaving=0;let confirmedQuery='',confirmedKind='รายวัน';let contractArchiveOpen=false;let contractSaving=0;let contractSwitchDraft={};let monthlyContractQuery="";let monthlyInviteCache=[];let token=sessionStorage.getItem('stayhub-control-token')||'',state=null,tab='overview',sound=false,previousFingerprint=null,polling=false,offline=false,pollDelay=60000,nextPoll=0;const el=id=>document.getElementById(id),page=el('page');
function n(tag,text,parent,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;if(parent)parent.appendChild(e);return e;}
function btn(text,parent,fn,cls){const b=n('button',text,parent,cls);b.type='button';b.onclick=async()=>{b.disabled=true;try{await fn();}catch(e){toast(e.message)}finally{b.disabled=false}};return b;}
function toast(text){el('toast').textContent=text;el('toast').classList.remove('hide');setTimeout(()=>el('toast').classList.add('hide'),9000)}
async function api(route,body){if(body&&offline)throw Error('ข้อมูลสำรอง: อ่านได้อย่างเดียว กรุณาเชื่อมต่อก่อนแก้ไข');const res=await fetch('/control-api/'+route,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});let data;try{data=await res.json()}catch{throw Error('เซิร์ฟเวอร์ไม่ได้ส่งข้อมูล JSON กลับมา')}if(!res.ok){if(res.status===401){sessionStorage.removeItem('stayhub-control-token');sessionStorage.removeItem('stayhub-control-snapshot');state=null;el('login').classList.remove('hide');el('workspace').classList.add('hide')}const err=Error(data.error||'HTTP '+res.status);err.status=res.status;throw err}return data;}
function can(p){return state.identity.permissions.includes(p)}function date(v){return v?new Date(v).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}):'—'}function online(h){return h&&Date.now()-h.at<60000}function card(title,parent=page){const c=n('section',undefined,parent,'card');n('h2',title,c);return c}function table(headers,rows,parent,decorate){if(!rows.length){n('p','ยังไม่มีข้อมูล',parent,'muted');return;}const wrap=n('div',undefined,parent,'tablewrap'),t=n('table',undefined,wrap),head=n('tr',undefined,t);headers.forEach(h=>n('th',h,head));let rowIndex=0;for(const values of rows){const tr=n('tr',undefined,t);for(const v of values){const td=n('td',undefined,tr);typeof v==='function'?v(td):n('span',String(v??'—'),td);}if(decorate)decorate(tr,rowIndex++);}}
function confirmAction(title,text,fn){el('modaltitle').textContent=title;el('modaltext').textContent=text;el('modal').classList.remove('hide');el('modalcancel').onclick=()=>el('modal').classList.add('hide');el('modalok').onclick=async()=>{el('modalok').disabled=true;try{const r=await fn();el('modal').classList.add('hide');toast(r.text||r.job?.result||'บันทึกแล้ว');await refresh();}catch(e){toast(e.message)}finally{el('modalok').disabled=false}};}
async function run(text){const r=await api('command',{text});if(r.job?.status==='confirm')confirmAction('ตรวจคำสั่งก่อนยืนยัน',r.job.summary,()=>api('confirm',{id:r.job.id}));else toast(r.text||'รับคำสั่งแล้ว รอคอมตอบกลับ');await refresh();}
async function refresh(){if(polling)return;polling=true;try{const fresh=await api('overview?section='+encodeURIComponent(tab));state=state&&state.identity.actor===fresh.identity.actor&&JSON.stringify(state.identity.permissions)===JSON.stringify(fresh.identity.permissions)?Object.assign({},state,fresh):fresh;offline=false;pollDelay=60000;try{sessionStorage.setItem('stayhub-control-snapshot',JSON.stringify({token:token,state:state,savedAt:Date.now()}))}catch{};sessionStorage.setItem('stayhub-control-token',token);el('login').classList.add('hide');el('workspace').classList.remove('hide');el('who').textContent=state.identity.owner?'เจ้าของ *Maxnum357 • ทุกสิทธิ์':'Admin • '+state.identity.permissions.length+' กลุ่มสิทธิ์';el('connection').textContent='ข้อมูลล่าสุด '+date(state.now)+' • คอม '+(online(state.bridge)?'ออนไลน์':'ไม่เชื่อมต่อ')+' • Codex '+(online(state.codexBridge)?state.codexBridge.status:'ไม่เชื่อมต่อ')+' • อัปเดตทุก 60 วินาทีเฉพาะแท็บที่เปิด'+(state.storage?.engine==='local-sqlite'?' • ฐานข้อมูล'+(state.storage.location==='server'?'บนเซิร์ฟเวอร์':'ในคอม')+' • สำรองล่าสุด '+date(state.storage.backupAt):'');const fp=JSON.stringify([(state.reports||[]).map(x=>[x.event_key,x.status]),(state.air||[]).map(x=>[x.room,!!x.confirmation]),state.jobs.map(x=>[x.id,x.status])]);if(previousFingerprint&&fp!==previousFingerprint&&sound){const a=new AudioContext(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);g.gain.value=.05;o.frequency.value=740;o.start();o.stop(a.currentTime+.15);o.onended=()=>a.close();}previousFingerprint=fp;renderTabs();render();}catch(e){offline=false;pollDelay=Math.min(pollDelay*2,900000);if(e.status!==401&&e.status!==403){try{const saved=JSON.parse(sessionStorage.getItem('stayhub-control-snapshot')||'null');if(!state&&saved&&saved.token===token&&Date.now()-saved.savedAt<8*3600000)state=saved.state;}catch{}if(state){offline=true;el('login').classList.add('hide');el('workspace').classList.remove('hide');el('who').textContent='ข้อมูลสำรอง • อ่านอย่างเดียว';renderTabs();render();}}el('connection').textContent=(offline?'ข้อมูลสำรอง ณ '+date(state.now)+' • อ่านอย่างเดียว • ':'')+'เชื่อมต่อไม่สำเร็จ: '+e.message;el('loginerror').textContent=e.message;if(state&&tab==='stayrooms')render();}finally{polling=false;nextPoll=Date.now()+pollDelay}}
